/**
 *  This test case verifies CBRD-26470: the maximum length of _db_stored_procedure.target_class.
 *
 *  An earlier revision of the PR defined target_class as varchar(PLCSQL_TARGET_CLASS_LEN = 512),
 *  so a Java SP whose class name was longer than 512 bytes could not be created (before the PR it
 *  was SP_ATTR_TARGET_CLASS_LEN = 1024). It is back to varchar(1024). _db_stored_procedure_code.name
 *  and _db_package_code.name, which only hold generated class names, stay 512.
 *
 *  The Java classes do not exist. A Java SP does not look for its class when it is created, so
 *  only the creation and the catalog are checked.
 *
 *  Coverage:
 *    Case 1: Java SP with a 600-char class name is created, target_class length 600
 *    Case 2: Java SP with a 1024-char class name is created, target_class length 1024
 *    Case 3: Java SP with a 512-char class name is created, target_class length 512 (regression)
 *    Case 4: Java SP with a 1025-char class name fails with "Data overflow"
 *    Case 5: PL/CSQL function is created and returns 7 (regression)
 *    Case 6: catalog: _db_stored_procedure.target_class 1024, _db_package_code.name 512,
 *            _db_stored_procedure_code.name 512
 */

--+ server-message on


evaluate 'Case 1: Java SP with a 600-char class name is created, target_class length 600';
create or replace function jf37_600 () return int as language java name '.m() return int';
select length (target_class) from _db_stored_procedure where sp_name = 'jf37_600';


evaluate 'Case 2: Java SP with a 1024-char class name is created, target_class length 1024';
create or replace function jf37_1024 () return int as language java name '.m() return int';
select length (target_class) from _db_stored_procedure where sp_name = 'jf37_1024';


evaluate 'Case 3: Java SP with a 512-char class name is created, target_class length 512 (regression)';
create or replace function jf37_512 () return int as language java name '.m() return int';
select length (target_class) from _db_stored_procedure where sp_name = 'jf37_512';


evaluate 'Case 4: Java SP with a 1025-char class name fails with Data overflow';
create or replace function jf37_1025 () return int as language java name '.m() return int';
select count(*) from _db_stored_procedure where sp_name = 'jf37_1025';


evaluate 'Case 5: PL/CSQL function (regression): 7';
create or replace function pf37 return int as begin return 7; end;
select pf37 () from dual;


evaluate 'Case 6: catalog: _db_package_code.name 512, _db_stored_procedure.target_class 1024, _db_stored_procedure_code.name 512';
select class_name, attr_name, prec from db_attribute where class_name in ('_db_stored_procedure', '_db_package_code', '_db_stored_procedure_code') and attr_name in ('target_class', 'name') order by 1, 2;

drop function jf37_600, jf37_1024, jf37_512, pf37;

--+ server-message off
